() => {
  const checkbox = document.querySelector('input[type="checkbox"][aria-label*="真人"]');
  if (checkbox) {
    checkbox.click();
    return { found: true, checked: checkbox.checked };
  }
  return { found: false };
}

() => {
  // Find all iframes (Turnstile uses an iframe)
  const iframes = document.querySelectorAll('iframe');
  const result = { iframeCount: iframes.length, iframes: [] };
  iframes.forEach((f, i) => {
    result.iframes.push({
      index: i,
      src: f.src,
      title: f.title,
      id: f.id
    });
  });
  // Also look for the Turnstile widget
  const widget = document.querySelector('[data-sitekey]');
  if (widget) {
    result.widget = {
      sitekey: widget.dataset.sitekey,
      action: widget.dataset.action
    };
  }
  return result;
}

() => {
  const iframes = Array.from(document.querySelectorAll('iframe')).map(f => f.src);
  const widget = document.querySelector('[data-sitekey]');
  return JSON.stringify({
    iframes,
    hasWidget: !!widget,
    sitekey: widget ? widget.dataset.sitekey : null,
    title: document.title,
    url: location.href
  });
}

() => {
  const checkbox = document.querySelector('input[type="checkbox"][aria-label*="真人"]');
  if (!checkbox) return 'NO CHECKBOX';

  // Get checkbox bounding box
  const rect = checkbox.getBoundingClientRect();
  const cx = rect.left + rect.width / 2;
  const cy = rect.top + rect.height / 2;

  // Dispatch a sequence of events
  const events = ['mousedown', 'mouseup', 'click'];
  events.forEach(type => {
    const event = new MouseEvent(type, {
      bubbles: true,
      cancelable: true,
      view: window,
      button: 0,
      clientX: cx,
      clientY: cy
    });
    checkbox.dispatchEvent(event);
  });

  return 'CLICKED at ' + cx + ',' + cy + ' checked=' + checkbox.checked;
}

() => {
  const checkbox = document.querySelector('input[type="checkbox"][aria-label*="真人"]');
  if (!checkbox) return 'NO CHECKBOX FOUND';

  // Force focus and click
  checkbox.focus();

  const rect = checkbox.getBoundingClientRect();
  const x = rect.left + rect.width / 2;
  const y = rect.top + rect.height / 2;

  // Dispatch multiple events to simulate real click
  ['pointerover', 'pointerenter', 'mousemove', 'pointerdown', 'mousedown', 'pointerup', 'mouseup', 'click'].forEach(type => {
    let event;
    if (type.startsWith('pointer')) {
      event = new PointerEvent(type, { bubbles: true, cancelable: true, clientX: x, clientY: y, pointerType: 'mouse' });
    } else {
      event = new MouseEvent(type, { bubbles: true, cancelable: true, clientX: x, clientY: y, button: 0 });
    }
    checkbox.dispatchEvent(event);
  });

  return 'Checkbox at (' + Math.round(x) + ',' + Math.round(y) + ') focused and clicked, checked=' + checkbox.checked;
}
